package br.com.gestao.sale; import br.com.gestao.sale.dto.*; import br.com.gestao.product.*; import br.com.gestao.stock.*; import br.com.gestao.finance.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.time.*; import java.util.*;
@Service public class SaleService{private final SaleRepository sales;private final ProductService products;private final FinancialEntryRepository finance;public SaleService(SaleRepository s,ProductService p,FinancialEntryRepository f){sales=s;products=p;finance=f;} public List<Sale> list(String email,boolean admin){return admin?sales.findAllByOrderByCreatedAtDesc():sales.findByCreatedByOrderByCreatedAtDesc(email);} @Transactional public Sale create(CreateSaleRequest q,String email){Sale sale=new Sale(q.customerName(),email);for(var line:q.items()){Product p=products.find(line.productId());if(!p.isActive())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Produto inativo: "+p.getName());products.move(p.getId(),MovementType.SALE,line.quantity(),"Venda",email);sale.addItem(new SaleItem(p.getId(),p.getName(),line.quantity(),p.getSalePrice()));}Sale saved=sales.save(sale);finance.save(new FinancialEntry(null,EntryType.INCOME,"Vendas","Venda #"+saved.getId(),saved.getTotal(),LocalDate.now(),true,LocalDateTime.now(),email));return saved;}}
